import subprocess, glob, os, json
EXE='/workspace/executable'
def game(bots, seed=5, w=8, h=8, extra=(), to=180):
    for f in glob.glob('*.hlt'): os.remove(f)
    cmd=[EXE,'-q','-s',str(seed),'-d',f'{w} {h}']+list(extra)+bots
    try:
        p=subprocess.run(cmd,capture_output=True,timeout=to)
    except subprocess.TimeoutExpired as e:
        return None, None, None, 'TIMEOUT'
    fs=glob.glob('*.hlt')
    raw=open(fs[0],'rb').read() if fs else None
    return p, raw, (fs[0] if fs else None), None

